'use client';

// Reference component: this file establishes the pattern all components follow.
// - cva for variants, cn() for merging
// - semantic tokens only, via arbitrary-value classes bound to CSS vars
// - all states: hover, focus-visible (global ring), active, disabled, loading
// - min touch target 44px (A3)
// - cursor-pointer is explicit (A14): Tailwind v4's preflight sets buttons to
//   cursor: default, so every interactive component must opt back in

import * as React from 'react';
import { Slot, Slottable } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/cn';

const buttonVariants = cva(
  [
    'inline-flex items-center justify-center gap-2 whitespace-nowrap select-none',
    'cursor-pointer rounded-[var(--radius-md)] font-medium',
    'transition-colors duration-[var(--duration-fast)]',
    'disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50',
    'min-h-[var(--touch-target-min)]',
    '[&_svg]:shrink-0',
  ],
  {
    variants: {
      variant: {
        primary: [
          'bg-[var(--color-action)] text-[var(--color-action-text)]',
          'hover:bg-[var(--color-action-hover)]',
          'active:opacity-90',
        ],
        secondary: [
          'bg-[var(--color-surface)] text-[var(--color-text-primary)]',
          'border border-[var(--color-border)]',
          'hover:bg-[var(--color-surface-hover)]',
          'active:bg-[var(--color-surface-active)]',
        ],
        ghost: [
          'text-[var(--color-text-primary)]',
          'hover:bg-[var(--color-surface-hover)]',
          'active:bg-[var(--color-surface-active)]',
        ],
        destructive: [
          'bg-[var(--color-status-error)] text-[var(--color-text-on-status)]',
          'hover:opacity-90 active:opacity-80',
        ],
      },
      size: {
        sm: 'h-9 min-h-9 px-3 text-[length:var(--text-sm)]',
        md: 'h-11 px-4 text-[length:var(--text-sm)]',
        lg: 'h-12 px-6 text-[length:var(--text-base)]',
        icon: 'h-11 w-11 p-0', // requires aria-label (A5)
      },
    },
    defaultVariants: { variant: 'primary', size: 'md' },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  loading?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, loading = false, disabled, children, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button';
    return (
      <Comp
        className={cn(buttonVariants({ variant, size }), className)}
        ref={ref}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        {...props}
      >
        {loading && (
          <span
            aria-hidden="true"
            className="size-4 animate-spin rounded-full border-2 border-current border-t-transparent"
          />
        )}
        {/* Slottable marks which child Slot merges into when asChild, so the
            loading sibling above no longer breaks the single-child rule. */}
        <Slottable>{children}</Slottable>
      </Comp>
    );
  }
);
Button.displayName = 'Button';

export { Button, buttonVariants };

"use client"

import * as React from "react"
import useEmblaCarousel, {
  type UseEmblaCarouselType,
} from "embla-carousel-react"

import { cn } from "@/lib/cn"
import { buttonVariants, type ButtonProps } from "@/components/ui/button"
import { ChevronLeft, ChevronRight } from "@/components/base-ds-icons/carousel"

type CarouselApi = UseEmblaCarouselType[1]
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>
type CarouselOptions = UseCarouselParameters[0]
type CarouselPlugin = UseCarouselParameters[1]

type CarouselProps = {
  opts?: CarouselOptions
  plugins?: CarouselPlugin
  orientation?: "horizontal" | "vertical"
  setApi?: (api: CarouselApi) => void
}

type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0]
  api: ReturnType<typeof useEmblaCarousel>[1]
  scrollPrev: () => void
  scrollNext: () => void
  canScrollPrev: boolean
  canScrollNext: boolean
} & CarouselProps

const CarouselContext = React.createContext<CarouselContextProps | null>(null)

function useCarousel() {
  const context = React.useContext(CarouselContext)

  if (!context) {
    throw new Error("useCarousel must be used within a <Carousel />")
  }

  return context
}

function Carousel({
  orientation = "horizontal",
  opts,
  setApi,
  plugins,
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & CarouselProps) {
  const [carouselRef, api] = useEmblaCarousel(
    {
      ...opts,
      axis: orientation === "horizontal" ? "x" : "y",
    },
    plugins
  )
  const [canScrollPrev, setCanScrollPrev] = React.useState(false)
  const [canScrollNext, setCanScrollNext] = React.useState(false)

  const onSelect = React.useCallback((api: CarouselApi) => {
    if (!api) return
    setCanScrollPrev(api.canScrollPrev())
    setCanScrollNext(api.canScrollNext())
  }, [])

  const scrollPrev = React.useCallback(() => {
    api?.scrollPrev()
  }, [api])

  const scrollNext = React.useCallback(() => {
    api?.scrollNext()
  }, [api])

  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault()
        scrollPrev()
      } else if (event.key === "ArrowRight") {
        event.preventDefault()
        scrollNext()
      }
    },
    [scrollPrev, scrollNext]
  )

  React.useEffect(() => {
    if (!api || !setApi) return
    setApi(api)
  }, [api, setApi])

  React.useEffect(() => {
    if (!api) return
    onSelect(api)
    api.on("reInit", onSelect)
    api.on("select", onSelect)

    return () => {
      api?.off("select", onSelect)
    }
  }, [api, onSelect])

  return (
    <CarouselContext.Provider
      value={{
        carouselRef,
        api: api,
        opts,
        orientation:
          orientation || (opts?.axis === "y" ? "vertical" : "horizontal"),
        scrollPrev,
        scrollNext,
        canScrollPrev,
        canScrollNext,
      }}
    >
      <div
        onKeyDownCapture={handleKeyDown}
        className={cn("relative", className)}
        role="region"
        aria-roledescription="carousel"
        data-slot="carousel"
        {...props}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  )
}

function CarouselContent({ className, ...props }: React.ComponentProps<"div">) {
  const { carouselRef, orientation } = useCarousel()

  return (
    <div
      ref={carouselRef}
      className="overflow-hidden"
      data-slot="carousel-content"
    >
      <div
        className={cn(
          "flex",
          orientation === "horizontal"
            ? "-ml-[var(--space-4)]"
            : "-mt-[var(--space-4)] flex-col",
          className
        )}
        {...props}
      />
    </div>
  )
}

function CarouselItem({ className, ...props }: React.ComponentProps<"div">) {
  const { orientation } = useCarousel()

  return (
    <div
      role="group"
      aria-roledescription="slide"
      data-slot="carousel-item"
      className={cn(
        "min-w-0 shrink-0 grow-0 basis-full",
        orientation === "horizontal"
          ? "pl-[var(--space-4)]"
          : "pt-[var(--space-4)]",
        className
      )}
      {...props}
    />
  )
}

function CarouselPrevious({
  className,
  variant = "secondary",
  size = "icon",
  loading = false,
  asChild: _asChild,
  disabled,
  type = "button",
  ...props
}: ButtonProps) {
  const { orientation, scrollPrev, canScrollPrev } = useCarousel()

  return (
    <button
      type={type}
      data-slot="carousel-previous"
      className={cn(
        buttonVariants({ variant, size }),
        "absolute cursor-pointer touch-manipulation rounded-[var(--radius-full)]",
        orientation === "horizontal"
          ? "inset-y-0 -left-12 my-auto"
          : "-top-12 left-1/2 -translate-x-1/2 rotate-90",
        className
      )}
      disabled={disabled || loading || !canScrollPrev}
      aria-busy={loading || undefined}
      onClick={scrollPrev}
      {...props}
    >
      <ChevronLeft aria-hidden="true" />
      <span className="sr-only">Previous slide</span>
    </button>
  )
}

function CarouselNext({
  className,
  variant = "secondary",
  size = "icon",
  loading = false,
  asChild: _asChild,
  disabled,
  type = "button",
  ...props
}: ButtonProps) {
  const { orientation, scrollNext, canScrollNext } = useCarousel()

  return (
    <button
      type={type}
      data-slot="carousel-next"
      className={cn(
        buttonVariants({ variant, size }),
        "absolute cursor-pointer touch-manipulation rounded-[var(--radius-full)]",
        orientation === "horizontal"
          ? "inset-y-0 -right-12 my-auto"
          : "-bottom-12 left-1/2 -translate-x-1/2 rotate-90",
        className
      )}
      disabled={disabled || loading || !canScrollNext}
      aria-busy={loading || undefined}
      onClick={scrollNext}
      {...props}
    >
      <ChevronRight aria-hidden="true" />
      <span className="sr-only">Next slide</span>
    </button>
  )
}

export {
  type CarouselApi,
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
  useCarousel,
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
